const rs=await Promise.allSettled(["game-017-log.json","game-017.sgf","AGENTS.md"].map(path=>tools.mcp__desk__read_file({path})));
const texts=rs.map(r=>{if(r.status!=="fulfilled")throw Error(String(r.reason));return r.value.content.filter(c=>c.type==="text").map(c=>c.text).join("\n")});
const saved=JSON.parse(texts[0]),sgfMoves=[...texts[1].matchAll(/;([BW])\[([a-i]{2})?\]/g)];
if(saved.moves.length!==87||saved.responses.length!==44||sgfMoves.length!==87)throw Error("Record length mismatch");
const cols="ABCDEFGHJ";sgfMoves.forEach((m,i)=>{const s=saved.moves[i];const coord=s.move==="pass"?"":"abcdefghi"[cols.indexOf(s.move[0])]+"abcdefghi"[9-Number(s.move[1])];if(m[1]!==s.color||(m[2]??"")!==coord)throw Error("SGF mismatch at "+i)});
if(!texts[2].includes("- Game 17: Black vs 20k")||!texts[2].includes("- Read game-017.md for the latest review")||!texts[2].includes("67. Game 17"))throw Error("Persistent instructions missing");
text({verified:true,moves:saved.moves.length,responses:saved.responses.length,result:saved.result,area:saved.finalCount.totals,sgfMatches:true,agentsUpdated:true});

